function acknowledgeQuestion(){if(!quizActive)return;$('readQuestionBtn').classList.add('hidden');$('answerArea').classList.remove('answers-locked');$('nextQuestionBtn').disabled=false;if(quizQuestions[quizIndex]?.type==='direct'){$('markCorrectBtn').disabled=false;$('markWrongBtn').disabled=false}if(timerSeconds>0)startPlayerTimer()}
function pausePlayerTimer(){if(playerDeadline){timerSeconds=Math.max(0,Math.ceil((playerDeadline-Date.now())/1000));updatePlayerTimer()}clearInterval(timerInterval);timerInterval=null;playerDeadline=null;$('timer').classList.add('paused');$('timer').classList.remove('running')}
function startPlayerTimer(){
  clearInterval(timerInterval);timerInterval=null;
  if(!quizActive||timerSeconds<=0)return;
  // El tiempo se calcula con una hora límite real para que el contador siempre avance.
  playerDeadline=Date.now()+timerSeconds*1000;
  $('timer').classList.remove('paused');$('timer').classList.add('running');
  timerInterval=setInterval(()=>{
    if(!quizActive||!playerDeadline){clearInterval(timerInterval);timerInterval=null;return;}
    timerSeconds=Math.max(0,Math.ceil((playerDeadline-Date.now())/1000));
    updatePlayerTimer();
    if(timerSeconds>5&&timerSeconds!==lastTimerBeep){lastTimerBeep=timerSeconds;timerBeep(false)}
    if(timerSeconds>0&&timerSeconds<=5&&Date.now()-lastTimerSoundAt>=300){lastTimerSoundAt=Date.now();timerBeep(true)}
    if(timerSeconds<=0){if(!alarmPlayed){alarmPlayed=true;timerAlarm()}clearInterval(timerInterval);timerInterval=null;playerDeadline=null;recordAnswer(true);}
  },200);
}
function updatePlayerTimer(){$('timer').textContent=`${String(Math.floor(Math.max(0,timerSeconds)/60)).padStart(2,'0')}:${String(Math.max(0,timerSeconds)%60).padStart(2,'0')}`;$('timer').classList.toggle('urgent',timerSeconds<=60)}
function addAnswer(text,letter,value){const btn=document.createElement('button');btn.type='button';btn.className='answer-option';btn.innerHTML=`<span class="letter">${letter}</span><span>${esc(text)}</span>`;btn.disabled=false;btn.addEventListener('click',()=>{selectedAnswer=value;document.querySelectorAll('.answer-option').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected')});$('answerArea').appendChild(btn)}
function nextQuestionAction(){
  if(!quizActive||$('readQuestionBtn').classList.contains('hidden')===false||$('nextQuestionBtn').disabled)return;
  pausePlayerTimer();
  recordAnswer(false,true);
  const q=quizQuestions[quizIndex];
  let correctText='';
  if(q.type==='multiple'){
    correctText=Number.isInteger(Number(q.correct)) && q.correct!==undefined && q.correct!==null && q.options && q.options[q.correct]!==undefined
      ? `${String.fromCharCode(65+Number(q.correct))}. ${q.options[Number(q.correct)]}`
      : 'Respuesta pendiente de verificar por el docente.';
  } else if(q.type==='truefalse') {
    correctText=q.correct===true||String(q.correct)==='true'?'Verdadero':q.correct===false||String(q.correct)==='false'?'Falso':'Respuesta pendiente de verificar por el docente.';
  } else {
    correctText=q.answer?.trim() || q.explanation?.trim() || 'La respuesta correcta no está registrada en el banco de preguntas.';
  }
  const feedback=$('answerFeedback');
  feedback.textContent=`Respuesta correcta: ${correctText}`;
  feedback.classList.add('correct-answer-reveal');
  $('nextQuestionBtn').disabled=true;
  document.querySelectorAll('.answer-option').forEach(b=>b.disabled=true);
  setTimeout(()=>{
    feedback.classList.remove('correct-answer-reveal');
    if(quizActive){if(timerSeconds<=0)finishQuiz();else nextQuestion();}
  },6000);
}
function normalize(s){return String(s??'').trim().toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[.,!?¿¡]/g,'')}
function recordAnswer(timeout,deferAdvance=false){const q=quizQuestions[quizIndex];let val=selectedAnswer;let correct=false;if(!timeout&&val!==null&&val!==''){if(q.type==='multiple')correct=Number(val)===Number(q.correct);else if(q.type==='truefalse')correct=String(val)===String(q.correct);else correct=val===true}const unanswered=timeout||(val===null||val==='');answers.push({q,correct,unanswered,timeout});if(timerSeconds<=0||timeout){while(answers.length<quizQuestions.length){answers.push({q:quizQuestions[answers.length],correct:false,unanswered:true,timeout:true})}finishQuiz();return}if(!deferAdvance)nextQuestion()}
