function resetGame(){clearInterval(timerInterval);$('directJudge').classList.add('hidden');playerDeadline=null;if(currentPlayerNumber<MAX_PLAYERS&&playerResults.length>0){currentPlayerNumber++;$('activePlayer').value=String(currentPlayerNumber);activePlayerName=$('player'+currentPlayerNumber).value.trim()||('Jugador '+currentPlayerNumber);$('resultPanel').classList.add('hidden');$('quizPanel').classList.add('hidden');$('chosenArea').classList.add('hidden');$('startQuizBtn').classList.add('hidden');$('spinStatus').textContent=`Turno de ${activePlayerName}. Gira la ruleta para comenzar sus 10 preguntas nuevas.`;$('spinBtn').disabled=false;$('spinBtn').textContent=`GIRAR RULETA — ${activePlayerName.toUpperCase()}`;selectedArea=null;answers=[];quizActive=false;$('gameView').scrollIntoView({behavior:'smooth'});return}if(playerResults.length>=MAX_PLAYERS){alert(`¡Concurso terminado! Los ${MAX_PLAYERS} jugadores completaron sus rondas. Se preparará un nuevo concurso.`)}currentPlayerNumber=1;usedQuestionKeys.clear();playerResults=[];$('activePlayer').value='1';$('spinBtn').textContent='GIRAR RULETA';$('spinBtn').disabled=false;$('resultPanel').classList.add('hidden');$('quizPanel').classList.add('hidden');$('chosenArea').classList.add('hidden');$('startQuizBtn').classList.add('hidden');$('spinStatus').textContent='Pulsa para elegir el área de inicio.';selectedArea=null;answers=[];quizActive=false;$('gameView').scrollIntoView({behavior:'smooth'})}
function renderDB(){const search=normalize($('searchInput').value),area=$('filterArea').value,type=$('filterType').value;const filtered=questions.filter(q=>(!area||q.area===area)&&(!type||q.type===type)&&normalize(q.text).includes(search));$('dbCount').textContent=`${filtered.length} de ${questions.length} preguntas`;if(!filtered.length){$('questionList').innerHTML='<div class="empty">No se encontraron preguntas. Prueba otro filtro o agrega una pregunta nueva.</div>';return} $('questionList').innerHTML=filtered.map(q=>`<article class="question-card"><div><span class="tag">${esc(q.area)}</span> <span class="tag">${esc(typeLabel(q.type))}</span><h3>${esc(q.text)}</h3><p>${q.type==='multiple'?(q.options||[]).map((o,i)=>`${String.fromCharCode(65+i)}. ${esc(o)}`).join(' · '):q.type==='truefalse'?'Respuesta: '+(q.correct?'Verdadero':'Falso'):'Respuesta: '+esc(q.answer||'No especificada')}</p></div><div class="card-actions"><button class="small-btn" data-edit="${q.id}">Editar</button><button class="small-btn delete" data-delete="${q.id}">Eliminar</button></div></article>`).join('');$('questionList').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editQuestion(b.dataset.edit));$('questionList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteQuestion(b.dataset.delete))}
function openDialog(q=null){$('questionForm').reset();$('questionId').value=q?.id||'';$('dialogTitle').textContent=q?'Editar pregunta':'Nueva pregunta';$('formArea').value=q?.area||AREAS[0];$('formType').value=q?.type||'multiple';$('formText').value=q?.text||'';$('formExplanation').value=q?.explanation||'';for(let i=0;i<4;i++)$('opt'+i).value=q?.options?.[i]||'';$('correctOption').value=q?.correct??0;$('tfCorrect').value=String(q?.correct??true);toggleFormType();$('questionDialog').showModal()}
function toggleFormType(){const t=$('formType').value;$('optionsFields').classList.toggle('hidden',t!=='multiple');$('tfFields').classList.toggle('hidden',t!=='truefalse')}
function editQuestion(id){const q=questions.find(q=>q.id===id);if(q)openDialog(q)}function deleteQuestion(id){const q=questions.find(q=>q.id===id);if(!q||!confirm('¿Eliminar esta pregunta?'))return;questions=questions.filter(q=>q.id!==id);saveQuestions()}
function saveForm(e){e.preventDefault();const type=$('formType').value,q={id:$('questionId').value||crypto.randomUUID(),area:$('formArea').value,type,text:$('formText').value.trim(),explanation:$('formExplanation').value.trim()};if(type==='multiple'){q.options=[0,1,2,3].map(i=>$('opt'+i).value.trim());if(q.options.some(x=>!x)){alert('Completa las cuatro alternativas.');return}q.correct=Number($('correctOption').value)}else if(type==='truefalse')q.correct=$('tfCorrect').value==='true';else q.answer=prompt('Escribe la respuesta esperada para la pregunta directa (puedes dejarla vacía):','')||'';const i=questions.findIndex(x=>x.id===q.id);if(i>=0)questions[i]=q;else questions.push(q);saveQuestions();$('questionDialog').close()}
function setupSelects(){['filterArea','formArea'].forEach(id=>{const el=$(id);AREAS.forEach(a=>{const o=document.createElement('option');o.value=a;o.textContent=a;el.appendChild(o)})})}
function exportDB(){const blob=new Blob([JSON.stringify(questions,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='preguntas_ruleta_educativa.json';a.click();URL.revokeObjectURL(url)}
function importDB(file){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data)||!data.every(q=>AREAS.includes(q.area)&&q.text&&q.type)){throw new Error('Formato inválido')}if(confirm(`¿Importar ${data.length} preguntas? Esto reemplazará el banco actual.`)){questions=data.map(q=>({...q,id:q.id||crypto.randomUUID()}));saveQuestions();alert('Preguntas importadas correctamente.')}}catch(e){alert('No se pudo importar. Verifica que sea un JSON exportado desde la ruleta.')}};reader.readAsText(file)}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(v=>{v.classList.toggle('active',v.id===b.dataset.view);v.classList.toggle('hidden',v.id!==b.dataset.view)});if(b.dataset.view==='dbView')renderDB()}));$('spinBtn').addEventListener('click',spin);$('startQuizBtn').addEventListener('click',startQuiz);$('readQuestionBtn').addEventListener('click',acknowledgeQuestion);$('markCorrectBtn').addEventListener('click',()=>{selectedAnswer=true;$('markCorrectBtn').classList.add('selected');$('markWrongBtn').classList.remove('selected')});$('markWrongBtn').addEventListener('click',()=>{selectedAnswer=false;$('markWrongBtn').classList.add('selected');$('markCorrectBtn').classList.remove('selected')});$('nextQuestionBtn').addEventListener('click',nextQuestionAction);$('newGameBtn').addEventListener('click',resetGame);$('addQuestionBtn').addEventListener('click',()=>openDialog());$('closeDialog').addEventListener('click',()=>$('questionDialog').close());$('cancelDialog').addEventListener('click',()=>$('questionDialog').close());$('formType').addEventListener('change',toggleFormType);$('questionForm').addEventListener('submit',saveForm);$('searchInput').addEventListener('input',renderDB);$('filterArea').addEventListener('change',renderDB);$('filterType').addEventListener('change',renderDB);$('exportBtn').addEventListener('click',exportDB);$('importFile').addEventListener('change',e=>{if(e.target.files[0])importDB(e.target.files[0]);e.target.value=''});setupSelects();drawWheel();renderDB();updateStats();
